def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Given a string containing multiple groups of nested parentheses, separate them into separate strings and return the list of those.
    Each group is balanced (each open brace is properly closed) and not nested within each other. Ignore any spaces in the input string.
    """
    groups = []
    current_group = ''
    stack = []

    for char in paren_string:
        if char.isalpha():
            continue
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) == 0:
                continue
            stack.pop()
            current_group += char
        else:
            current_group += char

        if len(stack) == 0 and current_group != '':
            groups.append(current_group)
            current_group = ''

    return groups

