def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with the given values
    grid = [[0] * N for _ in range(N)]
    for value in grid_values:
        grid[value[0]][value[1]] = value[2]

    # Initialize the maximum sum to 0
    max_sum = 0

    # Traverse the grid in a diagonal manner
    for i in range(N):
        for j in range(N):
            # If the current cell is not 0, it means it has not been traversed before
            if grid[i][j] != 0:
                # Update the maximum sum by adding the current cell value
                max_sum += grid[i][j]

                # Set the current cell value to 0 to mark it as traversed
                grid[i][j] = 0

                # Traverse the neighboring cells
                for k in range(i-1, i+2):
                    for l in range(j-1, j+2):
                        # If the neighboring cell is within the grid and has not been traversed before
                        if 0 <= k < N and 0 <= l < N and grid[k][l] != 0:
                            # Update the maximum sum by adding the neighboring cell value
                            max_sum += grid[k][l]

                            # Set the neighboring cell value to 0 to mark it as traversed
                            grid[k][l] = 0

    return max_sum

