    # sort the applicants by test score in descending order
    applicants.sort(key=lambda x: x[1], reverse=True)
    # determine the interview score cutoff
    cutoff = m * 1.5
    # initialize the list of qualified applicants
    qualified = []
    # iterate through the applicants and add them to the qualified list if they meet the cutoff
    for applicant in applicants:
        if applicant[1] >= cutoff:
            qualified.append(applicant)
    # return the interview score cutoff and the qualified applicants
    return (cutoff, qualified)

